import {backend} from './backend.js';
import {subjects as defaults} from './data.js';
import {escape as e} from './store.js';
let rows=null,lastError='';
export const subjectCatalog={
 names(){return rows===null?defaults.filter(x=>x!=='All subjects'):rows.map(x=>x.name);},
 filters(){return ['All subjects',...this.names()];},
 options(current=''){const names=this.names();return current&&!names.includes(current)?[current,...names]:names;},
 rows:()=>rows||[],
 error:()=>lastError,
 async load(){try{const fetched=await backend.read('lexamah_subjects');if(!Array.isArray(fetched)||fetched.some(x=>!x||typeof x.name!=='string'))throw new Error('Invalid subject catalog response.');rows=fetched;rows.sort((a,b)=>a.name.localeCompare(b.name));lastError='';return rows;}catch(err){lastError=err.message;return null;}},
 async add(raw){const name=String(raw).trim().replace(/\s+/g,' ');if(!name||name.length>120)throw new Error('Enter a subject name of 1–120 characters.');if(name.toLowerCase()==='all subjects')throw new Error('Choose a course name; All subjects is a filter.');if(this.names().some(x=>x.toLowerCase()===name.toLowerCase()))throw new Error('That subject already exists.');await backend.cloudSave('subjects',{name});await this.load();},
 async remove(id){await backend.cloudDelete('subjects',id);await this.load();}
};
export function subjectsScreen(){return `<section class="card"><div class="card-head"><div><h2>Subjects & Courses</h2><p>Add the subjects used by your content forms and student filters.</p></div><span class="pill">${subjectCatalog.rows().length} subjects</span></div>${subjectCatalog.error()?'<div class="notice">Subjects setup is required. Run supabase/subjects.sql in SQL Editor, then select Refresh.</div>':`<form id="subject-add-form" class="task-add"><input name="name" required maxlength="120" placeholder="e.g. Law of Evidence" aria-label="New subject"><button class="btn primary">Add subject</button></form><p id="subject-status" class="muted" role="status"></p>${subjectCatalog.rows().length?subjectCatalog.rows().map(x=>`<div class="row"><div class="row-copy"><strong>${e(x.name)}</strong></div><button class="btn danger" data-remove-subject="${e(x.id)}">Remove</button></div>`).join(''):'<p class="muted">No subjects yet. Add your first course above.</p>'}`}<p class="muted">Removing a subject removes it from the available dropdown options. Existing resources, quizzes and study history are retained.</p></section>`;}
export function bindSubjects(ui){const form=document.querySelector('#subject-add-form');if(!form)return;form.onsubmit=async event=>{event.preventDefault();const button=form.querySelector('button');button.disabled=true;try{await subjectCatalog.add(new FormData(form).get('name'));await ui.reload();ui.render();ui.toast('Subject added.');}catch(err){document.querySelector('#subject-status').textContent=err.message;}finally{button.disabled=false;}};}
export function removeSubject(id,ui){const item=subjectCatalog.rows().find(x=>x.id===id);if(!item)return;ui.modal('Remove subject?',`<p class="muted">Remove “${e(item.name)}” from the subject list? Its existing materials, recordings, notes, quizzes and history will be kept.</p><p id="subject-remove-status" class="muted" role="status"></p><div class="actions"><button class="btn danger" id="subject-confirm-remove">Remove subject</button><button class="btn" id="subject-cancel-remove">Keep subject</button></div>`);document.querySelector('#subject-cancel-remove').onclick=()=>document.querySelector('#dialog').close();document.querySelector('#subject-confirm-remove').onclick=async event=>{event.target.disabled=true;try{await subjectCatalog.remove(id);document.querySelector('#dialog').close();await ui.reload();ui.render();ui.toast('Subject removed. Existing content is retained.');}catch(err){document.querySelector('#subject-remove-status').textContent=err.message;event.target.disabled=false;}};}
